using System;using System.Collections.Generic;using System.Linq;using System.Reflection;using System.IO;using System.Web.Script.Serialization;
internal static class ObjectDynamicsCloudTests {
 static int checks;static List<object> vectors=new List<object>(),steps=new List<object>();static void Check(bool v,string m){checks++;if(!v)throw new Exception(m);}static void Near(double a,double b,string m,double eps=1e-9){Check(Math.Abs(a-b)<=eps,m+": "+a+" != "+b);}
 static Track E(string id="e"){return new Track{id=id,name=id,kind="emitter",start=0,end=0,x=100,y=200,count=1,speed=3,life=1000};}
 static EditorState S(params Track[] t){var s=new EditorState{duration=1000,tracks=t.ToList()};Motion.Normalize(s);return s;}
 static SimBullet B(BulletWorld w,string id="e"){return w.bullets.Single(b=>b.source.id==id);}
