 static BulletAction A(string type,int start,double to){return new BulletAction{type=type,start=start,duration=0,to=to};}
 static object Values(SimBullet b){return new{b.x,b.y,b.speed,b.direction,b.acceleration,b.friction,b.gravity,b.gravityDirection,b.turn};}
