 foreach(string p in ObjectDynamics.Fields){var nullTrack=Json.Read<Track>("{\""+p+"\":null}");ObjectDynamics.Normalize(nullTrack);Near(Motion.Base(nullTrack,p),0,"explicit null zero");}Near(Json.Read<Track>("{}").bulletGravityDirection,270,"missing angle default");
 // Exact reused gravity contract, including negative speed/gravity and near-zero headings.
 foreach(double speed in new[]{-12.0,-1.0,0.0,1.0,12.0})foreach(double direction in new[]{-725.0,0.0,90.0,180.0,270.0,723.0})foreach(double gravity in new[]{-1.0,0.0,1e-12,1.0,12.0})foreach(double angle in new[]{0.0,90.0,270.0}){
  var b=new SimBullet{speed=speed,direction=direction,gravity=gravity,gravityDirection=angle};ObjectDynamics.Gravity(b);double a=direction*Math.PI/180,g=angle*Math.PI/180,vx=Math.Cos(a)*speed+Math.Cos(g)*gravity,vy=-Math.Sin(a)*speed-Math.Sin(g)*gravity,mag=Math.Sqrt(vx*vx+vy*vy);Near(b.speed,gravity==0?speed:mag,"vector speed");Near(b.direction,gravity==0||mag<=1e-9?direction:ExpressionContext.Direction(0,0,vx,vy),"vector direction");vectors.Add(new{speed,direction,gravity,angle,result=Values(b)});
 }
 foreach(bool move in new[]{false,true})foreach(double speed in new[]{-3.0,-.2,0.0,.2,3.0})foreach(double gravity in new[]{-.4,0.0,.4}){
  var t=E();t.moveOnBirth=move;t.speed=speed;t.bulletAcceleration=.3;t.bulletFriction=.5;t.bulletGravity=gravity;t.bulletGravityDirection=137;t.bulletActions.Add(A("turn",0,17));var w=new BulletWorld(S(t));w.Seek(0);if(!move){Near(B(w).x,100,"default birth x");Near(B(w).speed,speed,"default birth speed");}var before=Values(B(w));w.Seek(1);steps.Add(new{before,after=Values(B(w)),stop=false});
 }
 // Spawn-context capture must precede member offsets or explicit origin/speed overrides.
 {var t=E();t.motion="velocity";t.velocityX=2;t.emissionShape="line";t.emitWidth=100;t.expressions["bulletGravity"]="x/100+i";t.expressions["bulletGravityDirection"]="y+frame";t.expressions["bulletAcceleration"]="x/1000";t.expressions["bulletFriction"]="-x";var w=new BulletWorld(S(t));w.Seek(0);var b=w.Spawn(w.State.tracks[0],4,1,2,0,new System.Drawing.PointF(999,777),45,2);Near(b.gravity,2.08,"emitter pose gravity");Near(b.gravityDirection,204,"emitter pose gravity angle");Near(b.acceleration,.108,"emitter acceleration");Near(b.friction,0,"sampled negative friction clamps");Near(b.x,999,"origin override separate");}
 // An age action captures the current position once; persistent turn follows it before gravity.
 {var t=E();t.speed=5;t.bulletActions.Add(A("turn",0,7));var capture=A("gravityDirection",0,0);capture.duration=100;capture.condition="age>=3";capture.once=true;capture.expression="point_direction(x,y,400,304)+40";t.bulletActions.Add(capture);var dir=A("direction",3,0);dir.expression=capture.expression;t.bulletActions.Add(dir);t.bulletActions.Add(A("speed",3,2));t.bulletActions.Add(A("gravity",3,.1));var w=new BulletWorld(S(t));w.Seek(2);var prior=B(w);double angle=ExpressionContext.Direction(prior.x,prior.y,400,304)+40;double x=prior.x,y=prior.y;w.Seek(3);Near(B(w).gravityDirection,angle,"capture current x y");var expected=new SimBullet{direction=angle+7,speed=2,gravity=.1,gravityDirection=angle};ObjectDynamics.Gravity(expected);Near(B(w).direction,expected.direction,"turn before gravity");Near(B(w).x,x+Math.Cos(expected.direction*Math.PI/180)*expected.speed,"phase movement x");w.Seek(9);Near(B(w).gravityDirection,angle,"stored not live");Check(B(w).firedActions.Count==1,"one capture");w.Seek(2);w.Seek(9);Near(B(w).gravityDirection,angle,"rewind recapture");}
 // Control expressions read the current bullet rather than the emitter pose.
 {var t=E();var c=new Track{id="c",kind="control",start=3,end=3,targetSource=t.id,controlAction="gravityDirection",controlExpression="x+y"};var w=new BulletWorld(S(t,c));w.Seek(2);double angle=B(w).x+B(w).y;w.Seek(3);Near(B(w).gravityDirection,angle,"control current coordinates");}
 foreach(string type in new[]{"stop-bullets","reset-motion","orbit-bullets"}){
  var t=E();t.bulletAcceleration=.3;t.bulletFriction=.2;t.bulletGravity=.5;t.bulletGravityDirection=83;t.bulletActions.Add(A("turn",0,11));t.bulletActions.Add(A("gravity",2,5));var e=Event(type);e.controlValue=2;e.controlFrom=10;e.eventTurn=3;e.eventCenterX=0;e.eventCenterY=0;e.eventOrbitSpeed=2;var w=new BulletWorld(S(t,e));w.Seek(0);double x=B(w).x,y=B(w).y;w.Seek(1);var b=B(w);if(type=="stop-bullets"){Near(b.x,x,"stop x");Near(b.y,y,"stop y");Near(b.direction,11,"stop keeps turn");Near(b.gravity,.5,"stop keeps gravity");}else {Near(b.gravity,0,"reset/orbit clears gravity");Near(b.gravityDirection,270,"reset angle default");}w.Seek(2);if(type!="stop-bullets")Near(B(w).gravity,0,"reset blocks later gravity action");}
 // Direct orbit bypass remains independent even if a later ordinary control sets gravity.
 {var t=E();t.bulletGravity=.9;var e=Event("orbit-bullets");e.eventCenterX=0;e.eventCenterY=0;e.eventOrbitSpeed=4;var c=new Track{id="c",kind="control",start=2,end=2,controlAction="gravity",controlValue=9};var w=new BulletWorld(S(t,e,c));w.Seek(2);Near(B(w).speed,0,"orbit bypass gravity");Near(B(w).gravity,9,"control after orbit stored");Near(Math.Sqrt(B(w).x*B(w).x+B(w).y*B(w).y),Math.Sqrt(50000),"orbit radius");}
 // Both ordinary snapshot and generated reusable-object group copy reset to event dynamics.
 foreach(bool destroy in new[]{false,true}){var t=E();t.bulletGravity=.5;t.bulletGravityDirection=10;var e=Event("group-copy");e.eventGroup="g";e.eventCopyDestroyOriginal=destroy;e.controlValue=2;e.eventCopyLife=100;var s=S(t,e);s.timelineGroups=new List<TimelineGroup>{new TimelineGroup{id="g",name="g",lanes=new List<int>{t.lane}}};var w=new BulletWorld(s);w.Seek(1);var copy=w.bullets.Single(b=>b.generation==1);Near(copy.gravity,0,"copy zero gravity");Near(copy.gravityDirection,270,"copy default direction");}
 // Independent snapshot, undo, JSON, copy and preset persistence.
 {var t=E();t.bulletAcceleration=.2;t.bulletFriction=.3;t.bulletGravity=-.4;t.bulletGravityDirection=201;var a=A("gravityDirection",7,202);a.expression="x+y";t.bulletActions.Add(a);var s=S(t);var undo=new UndoHistory();undo.Undo.Push(new UndoEntry(new UndoSnapshot{state=s}));var ser=new JavaScriptSerializer();var copies=new[]{s.Snapshot().tracks[0],BulletSystem.CloneTracks(s.tracks)[0],ser.Deserialize<EditorState>(ser.Serialize(s)).tracks[0],TrackPreset.Capture("gravity",s.tracks,50).Instantiate(0,50)[0],undo.Undo.Pop().Restore().state.tracks[0]};foreach(var c in copies){Near(c.bulletGravity,-.4,"saved gravity");Near(c.bulletGravityDirection,201,"saved angle");Check(c.bulletActions[0].expression=="x+y","saved capture expression");}var clone=new SimBullet{gravity=.4,gravityDirection=123}.Clone();Near(clone.gravity,.4,"bullet clone magnitude");Near(clone.gravityDirection,123,"bullet clone angle");}
 // Patterns and FPS presets apply ratio-squared only to acceleration-like units.
 {var t=E();t.bulletGravity=.4;t.bulletAcceleration=.2;t.bulletFriction=.3;t.bulletGravityDirection=123;t.expressions["bulletGravity"]="frame*.01";t.keyframes.Add(new Keyframe{frame=0,property="bulletAcceleration",value=.2,expression="frame*.02"});t.bulletActions.Add(new BulletAction{type="gravity",start=2,duration=0,from=.2,to=.4,expression="age*.01",expressions=new Dictionary<string,string>{{"to","age*.02"}}});t.bulletActions.Add(A("gravityDirection",2,77));var clip=new Track{id="clip",kind="pattern",start=10,end=100,timeScale=2,children=new List<Track>{t}};var expanded=BulletSystem.Expand(S(clip)).tracks[0];Near(expanded.bulletGravity,1.6,"clip gravity rate");Near(expanded.bulletFriction,1.2,"clip friction rate");Near(expanded.bulletGravityDirection,123,"clip direction fixed");Near(expanded.bulletActions[0].to,1.6,"clip action");Check(expanded.bulletActions[0].expression.Contains("*4"),"action expression scale");Check(expanded.keyframes[0].expression.Contains("*4"),"key expression scale");Near(expanded.bulletActions[1].to,77,"angle action units");var preset=TrackPreset.Capture("g",new[]{t},50).Instantiate(0,100)[0];Near(preset.bulletGravity,.1,"preset gravity rate");Near(preset.bulletGravityDirection,123,"preset angle");}
 // Delays and template birth sample their own clocks, while birth motion is consumed once.
 {var t=E();t.count=3;t.indexDelay=2;t.moveOnBirth=true;t.bulletGravity=1;t.bulletGravityDirection=0;t.speed=0;var w=new BulletWorld(S(t));w.Seek(3);Check(w.bullets.Count==3,"delayed instances exist");var second=w.bullets.Single(b=>b.index==1);Near(second.x,103,"delayed birth moved exactly twice");Near(second.speed,2,"delayed gravity twice");}
 {var p=E("p");p.spawnActions.Add(new BulletAction{type="spawn",templateId="child",start=0,duration=0,count=1});var child=E("child");child.templateOnly=true;child.moveOnBirth=true;child.speed=0;child.x=child.y=0;child.bulletGravity=1;child.bulletGravityDirection=0;var w=new BulletWorld(S(p,child));w.Seek(0);Near(B(w,"child").speed,1,"template birth gravity");Near(B(w,"child").x,101,"template birth origin");}
 // Actual checkpoint restore retains the captured gravity direction and scalar acceleration.
 {var t=E();t.bulletGravity=.03;t.bulletGravityDirection=83;t.bulletActions.Add(A("gravityDirection",100,121));var w=new BulletWorld(S(t));w.Seek(420);var before=Values(B(w));double x=B(w).x,y=B(w).y;Check(w.CheckpointCount>=2,"checkpoints exist");w.Seek(215);w.Seek(420);Near(B(w).x,x,"checkpoint x");Near(B(w).y,y,"checkpoint y");Near(B(w).gravityDirection,121,"checkpoint captured direction");}
 foreach(double value in new[]{Double.NaN,Double.PositiveInfinity,1000001.0}){var t=E();t.bulletGravity=value;bool invalid=false;try{S(t);}catch(FormatException){invalid=true;}Check(invalid,"invalid base rejected");} {var t=E();t.bulletFriction=-1;bool invalid=false;try{S(t);}catch(FormatException){invalid=true;}Check(invalid,"negative base friction rejected");}
 {var t=E();ObjectProperties.Attach(t,5,0);foreach(string f in ObjectDynamics.Fields){Check(Motion.Fields(t).Contains(f),"UI field "+f);Check(Motion.Name(f)!=f,"UI translated name");}Check(BulletSystem.ActionTypes.Length==BulletSystem.ActionNames.Length,"action labels aligned");var clamp=typeof(MainForm).GetMethod("ClampValue",BindingFlags.Static|BindingFlags.NonPublic);Near((double)clamp.Invoke(null,new object[]{"bulletFriction",-2.0,false}),0,"friction UI clamp");Near((double)clamp.Invoke(null,new object[]{"bulletGravity",-2.0,false}),-2,"signed gravity UI");}
 File.WriteAllText(args.Length==0?"build/gravity-csharp-results.json":args[0],new JavaScriptSerializer{MaxJsonLength=10000000}.Serialize(new{checks,vectors,steps}));Console.WriteLine("PASS ObjectDynamics "+checks+" checks; "+vectors.Count+" vectors; "+steps.Count+" steps");
